parameters.jsCode:
const entrada = $input.first().json.output;

let parsed = { message: ""};

try {
  // Verificamos si es un string y parece JSON (entre llaves)
  if (typeof entrada === "string" && entrada.trim().startsWith("{") && entrada.trim().endsWith("}")) {
    parsed = JSON.parse(entrada);
  } else if (typeof entrada === "object") {
    parsed = entrada;
  } else {
    // Si es texto plano, lo usamos como message
    parsed.message = entrada;
  }
} catch (error) {
  // Si algo falla, devuelve un mensaje genérico
  parsed.message = "error";
}

return parsed;

// Generar número random entero entre 1 y 5
const numeroRandom = Math.floor(Math.random() * 10) + 1;

// Tabla de equivalencias
const configuracion = {
  1: { plantilla: 55961, salesbot: 57463 }, //envio_mensaje_1
  2: { plantilla: 55963, salesbot: 57465 }, //envio_mensaje_2
  3: { plantilla: 55965, salesbot: 57467 }, //envio_mensaje_3
  4: { plantilla: 55967, salesbot: 57469 }, //envio_mensaje_4
  5: { plantilla: 55969, salesbot: 57471 }, //envio_mensaje_5
  6: { plantilla: 55971, salesbot: 57473 }, //envio_mensaje_6
  7: { plantilla: 55973, salesbot: 57475 }, //envio_mensaje_7
  8: { plantilla: 55975, salesbot: 57477 }, //envio_mensaje_8
  9: { plantilla: 55977, salesbot: 57479 }, //envio_mensaje_9
  10: { plantilla: 55979, salesbot: 57481 }, //envio_mensaje_10
};

// Obtener valores según el número random
const resultado = configuracion[numeroRandom];

return [
  {
    json: {
      random: numeroRandom,
      plantilla: resultado.plantilla,
      salesbot: resultado.salesbot
    }
  }
];

conditions.leftValue:
={{ (() => {
  const text = $json.message.text || '';

  // 1. Detecta si es SOLO el link de sticker
  const onlySticker = /^https?:\/\/[^\s]*lookaside\.fbsbx\.com[^\s]*$/i.test(text.trim());

  // 2. Limpia emojis/símbolos y valida si queda texto real
  const cleanText = text
    .replace(/https?:\/\/[^\s]*lookaside\.fbsbx\.com[^\s]*/gi, '')
    .replace(/[^\p{L}\p{N}\s]/gu, '')
    .trim();

  // 3. Condición final
  return !onlySticker && cleanText.length > 1;
})() }}
